var BARS=[
  {id:1,name:"Cafe v lese",district:"Vršovice",hood:"Praha 10",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ne",craft:"Craft",beers:[{name:"Chříč Balanc 0% IPA",cat:"Craft",serve:"Čepované"},{name:"Paulaner Weissbier 0%",cat:"Tradiční",serve:"Lahvové"},{name:"Birell",cat:"Birell",serve:"Lahvové"}],hours:"Pondělí 16–2\nÚterý 16–2\nStředa 16–2\nČtvrtek 16–2\nPátek 16–2\nSobota 16–2\nNeděle 16–0",address:"Krymská 12, 101 00 Praha 10 – Vršovice",desc:"Moderní kulturní prostor a kavárna v srdci Vršovic, která kombinuje retro interiér s živým hudebním a společenským programem. Nabízí neformální atmosféru pro setkávání u kávy nebo drinku s možností návštěvy koncertů a performancí v podzemním klubu.",descEn:"A modern cultural space and café in the heart of Vršovice, pairing a retro interior with a busy programme of live music and events. The mood is informal — somewhere to meet over coffee or a drink, with concerts and performances running in the basement club.",lat:50.0713476,lng:14.448464},
  {id:2,name:"Dejvická Sokolovna",district:"Dejvice",hood:"Praha 6",type:"Restaurace",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Birell",beers:[{name:"Birell",cat:"Birell",serve:"Čepované"}],hours:"Pondělí 10:30–23\nÚterý 10:30–23\nStředa 10:30–0\nČtvrtek 10:30–15\nPátek 10:30–0\nSobota 11–23\nNeděle 11–22",address:"Dejvická 181/2, 160 00 Praha 6 – Dejvice",desc:"Moderní česká restaurace s více než stoletou tradicí, která se zaměřuje na poctivou domácí kuchyni a čepované tankové pivo. Nabízí neformální atmosféru klasické pivnice / hospody v příjemném moderním interiéru.",descEn:"A modern Czech restaurant with more than a century of history behind it, built around honest home cooking and tank-fresh beer on tap. It keeps the easy feel of a classic Czech pub inside a comfortable contemporary interior.",lat:50.0980662,lng:14.4047094},
  {id:3,name:"Automat Matuška Hradčanská",district:"Dejvice",hood:"Praha 6",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Bylinný Střízlivec",cat:"Craft",serve:"Čepované"},{name:"Preisler-Motuečka",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11:30–0\nÚterý 11:30–0\nStředa 11:30–0\nČtvrtek 11:30–0\nPátek 11:30–0\nSobota 12–0\nNeděle 12–22",address:"Dejvická 184/4, 160 00 Praha 6 – Dejvice",desc:"Moderní řemeslný výčep a bistro zaměřené na prezentaci piva z rodinného pivovaru Matuška a kvalitní street food. Nabízí minimalistický design s vysokým standardem servisu, kde se klade důraz na čerstvost piva a párování s moderní gastronomií.",descEn:"A craft taproom and bistro showcasing beer from the family-run Matuška brewery alongside well-made street food. Minimalist design, a high standard of service, and real attention to beer freshness and how it pairs with modern cooking.",lat:50.0980426,lng:14.4042846},
  {id:4,name:"Automat Matuška JZP",district:"Vinohrady",hood:"Praha 3",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Bylinný Střízlivec",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11:30–0\nÚterý 11:30–0\nStředa 11:30–0\nČtvrtek 11:30–0\nPátek 11:30–0\nSobota 12–0\nNeděle 12–22",address:"nám. J. z Poděbrad 16, 130 00 Praha 3 – Vinohrady",desc:"Mladší bratr dejvického Automatu. Moderní řemeslný výčep a bistro zaměřené na prezentaci piva z rodinného pivovaru Matuška a kvalitní street food. Nabízí minimalistický design s vysokým standardem servisu, kde se klade důraz na čerstvost piva a párování s moderní gastronomií.",descEn:"The younger sibling of the Dejvice original. A craft taproom and bistro showcasing beer from the family-run Matuška brewery alongside well-made street food, with the same minimalist design and attention to freshness and food pairing.",lat:50.078140,lng:14.452252},
  {id:5,name:"Dva Kohouti",district:"Karlín",hood:"Praha 8",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Elektrárna Proovan IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 15–1\nÚterý 15–1\nStředa 15–1\nČtvrtek 15–1\nPátek 15–1\nSobota 12–1\nNeděle 12–22",address:"Sokolovská 81/55, 186 00 Praha 8 – Karlín",desc:"Inovativní koncept spojující řemeslný pivovar s výčepem přímo v srdci Karlína. Nabízí živou, neformální atmosféru s důrazem na čerstvě uvařené pivo a sdílený prostor, který se během dne mění z klidného dvora na rušné společenské centrum.s",descEn:"An inventive setup that puts a craft brewery and its taproom under one roof in the middle of Karlín. The atmosphere is lively and informal, built around beer brewed metres away and a shared courtyard that shifts through the day from quiet yard to busy meeting place.",lat:50.09349,lng:14.4468455},
  {id:6,name:"U Sadu",district:"Žižkov",hood:"Praha 3",type:"Hospoda",serve:"Lahvové",garden:"Ano",food:"Ano",craft:"Birell",beers:[{name:"Birell",cat:"Birell",serve:"Lahvové"}],hours:"Pondělí 8–2\nÚterý 8–4\nStředa 8–4\nČtvrtek 8–4\nPátek 8–4\nSobota 8–4\nNeděle 8–2",address:"Škroupovo nám. 1282/5, 130 00 Praha 3 – Žižkov",desc:"Tradiční žižkovská restaurace a bar s téměř nepřetržitým provozem, který je kultovním místem pražské undergroundové scény. Nabízí unikátní interiér plný historických artefaktů, širokou nabídku české i mezinárodní kuchyně včetně snídaní a výběr z čepovaných piv i belgických lahvových speciálů.",descEn:"A Žižkov institution, open almost around the clock and a fixture of Prague's underground scene. The interior is crammed with historical oddities, the menu runs from Czech classics to international dishes and breakfast, and the beer list covers draught Czech lagers as well as Belgian bottled specials.",lat:50.0805308,lng:14.4492094},
  {id:7,name:"U Houdků",district:"Žižkov",hood:"Praha 3",type:"Hospoda",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Birell",beers:[{name:"Birell",cat:"Birell",serve:"Čepované"}],hours:"Pondělí 11–0\nÚterý 11–0\nStředa 11–0\nČtvrtek 11–0\nPátek 11–0\nSobota 11–0\nNeděle 11–23",address:"Bořivojova 693/110, 130 00 Praha 3 – Žižkov",desc:"Tradiční pražská restaurace na Žižkově s historií sahající do roku 1923, která je vyhlášená nadstandardními porcemi klasické české kuchyně. Nabízí autentické prostředí staré Prahy a vyhledávanou letní zahrádku v klidném vnitrobloku.",descEn:"A traditional Prague restaurant in Žižkov, serving since 1923 and known for portions of Czech classics that defeat most people. The setting is authentic old Prague, and the summer garden in the quiet courtyard is worth seeking out.",lat:50.0824601,lng:14.445716},
  {id:8,name:"U Habásků",district:"Žižkov",hood:"Praha 3",type:"Hospoda",serve:"Lahvové",garden:"Ne",food:"Drobné občerstvení",craft:"Birell",beers:[{name:"Birell",cat:"Birell",serve:"Lahvové"}],hours:"Pondělí 16–0\nÚterý 16–0\nStředa 16–0\nČtvrtek 16–0\nPátek 16–2\nSobota 16–2\nNeděle 16–23",address:"Husinecká 29, 130 00 Praha 3 – Žižkov",desc:"Klasická žižkovská sousedská hospoda s domáckou atmosférou, která si zachovává ráz poctivého lokálního podniku. Nabízí tradicni výčep, jednoduchou kuchyni a klidné zázemí pro stálé hosty i návštěvníky hledající klid mimo hlavní turistické trasy.",descEn:"A classic Žižkov neighbourhood pub with a homely feel, holding on to the character of a proper local. Straightforward beer, simple cooking and a calm corner for regulars and anyone looking to get off the tourist routes.",lat:50.0858298,lng:14.4464288},
  {id:9,name:"Dno Pytle",district:"Vinohrady",hood:"Praha 2",type:"Hospoda",serve:"Čepované",garden:"Ne",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 16–23\nÚterý 16–1\nStředa 16–1\nČtvrtek 16–1\nPátek 16–1\nSobota 18–1\nNeděle 18–23",address:"Vinohradská 63, 120 00 Praha 2 – Vinohrady",desc:"Moderní nekuřácká pivnice v centru Prahy zaměřená na prezentaci produktů z českých i zahraničních minipivovarů. Na osmi pípách nabízí pravidelně obměňovanou nabídku pivních speciálů, kterou doplňuje široký výběr lahvových piv a plechovek od různých craftových pivovarů a několik druhů kvalitních klobás na grilu.",descEn:"A modern non-smoking beer hall in central Prague focused on Czech and international microbreweries. Eight taps rotate constantly, backed by a wide selection of bottles and cans from craft brewers and a few kinds of good sausage off the grill.",lat:50.0771063,lng:14.4428117},
  {id:10,name:"Pivovar Uhříněves",district:"Uhříněves",hood:"Praha 22",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Alois Šofér",cat:"Craft",serve:"Čepované"},{name:"Alois Šofér",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–23\nÚterý 11–23\nStředa 11–23\nČtvrtek 11–23\nPátek 11–23\nSobota 11–23\nNeděle 11–22",address:"K Sokolovně 38, 104 00 Praha 22 – Uhříněves",desc:"Tradiční restaurace Pivovaru Uhříněves, která se zaměřuje na poctivou českou kuchyni a vlastní nepasterizovaná piva včetně nealko varianty. Nabízí prostorný rustikální interiér a klidnou venkovní zahrádku, ideální pro rodinné obědy i větší společenská setkání.",descEn:"The taproom restaurant of the Uhříněves brewery, built around honest Czech cooking and their own unpasteurised beers, including an alcohol-free version. The rustic interior is roomy and the quiet garden suits family lunches and larger gatherings alike.",lat:50.0296992,lng:14.6049522},
  {id:11,name:"Fatfuck Vinohradská",district:"Vinohrady",hood:"Praha 2",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Alois Šofér",cat:"Craft",serve:"Čepované"}],hours:"Pondělí Zavřeno\nÚterý 12–22\nStředa 12–22\nČtvrtek 12–22\nPátek 12–22\nSobota 12–22\nNeděle 10–21",address:"Vinohradská 1241/67, 120 00 Praha 2 – Vinohrady",desc:"Moderní bistro na Vinohradech specializované na autentické „smashed“ burgery připravované z prémiových surovin. Nabízí minimalistický, dynamický koncept s důrazem na kvalitu masa a domácí dresinky, doplněný o čepované pivo z Pivovaru Uhříněves včetně jejich nealkoholického piva Alois Šofér.",descEn:"A modern bistro in Vinohrady specialising in proper smashed burgers made from premium ingredients. The concept is minimal and fast-moving, with real care for the meat and house-made dressings, served alongside draught beer from Pivovar Uhříněves — including their alcohol-free Alois Šofér.",lat:50.0771324,lng:14.4435489},
  {id:12,name:"Kasárny Karlín",district:"Karlín",hood:"Praha 8",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Tradiční",beers:[{name:"Bakalář nealko",cat:"Tradiční",serve:"Čepované"},{name:"Maisel´s IPA Alkoholfrei",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 11:30–16\nÚterý 11:30–22\nStředa 11:30–22\nČtvrtek 11:30–22\nPátek 11:30–22\nSobota 11:30–22\nNeděle 11:30–22",address:"Prvního pluku 20/2, 186 00 Praha 8 – Karlín",desc:"Kulturní oáza v srdci Karlína, kde se vojenská přísnost proměnila v uvolněný prostor pro film, hudbu a setkávání. Na rozlehlém nádvoří Kasáren chutná pivo nejlépe pod širým nebem, ať už sedíte u ohniště nebo v letním kině. K téhle unikátní industriální atmosféře si tu můžete vždycky dát poctivé nealko. Ideální bod pro dlouhé letní večery, kdy zážitek nepotřebuje žádná promile.",descEn:"A cultural oasis in the heart of Karlín, where military severity has given way to a relaxed space for film, music and meeting people. Beer tastes best outdoors on the vast parade-ground courtyard, whether you are by the fire pit or at the open-air cinema. There is always a decent alcohol-free option to go with the industrial setting — ideal for long summer evenings that need no alcohol to work.",lat:50.090058,lng:14.443827},
  {id:13,name:"elpíčko",district:"Libeň",hood:"Praha 8",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Birell",cat:"Birell",serve:"Lahvové"},{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–1\nÚterý 16–1\nStředa 16–1\nČtvrtek 16–1\nPátek 16–1\nSobota 16–1\nNeděle 16–23",address:"Zenklova 305/11, 180 00 Praha 8 – Libeň",desc:"Skutečná oáza uprostřed rustikální Palmovky. V létě nabízí velkorysou zahrádku pro nekonečný chill a v zimě stylový suterénní bar, kde pochopíš, proč je tohle místo legendou. V nabídce mají kromě birella nealko novinku z Vinohradského pivovaru. Je to ideální bod pro každého, kdo hledá poctivé pití a jedinečnou atmosféru.",descEn:"A genuine oasis in the middle of rough-edged Palmovka. Summer brings a generous garden built for endless lounging; winter moves you into a stylish basement bar where the place's legendary status starts to make sense. Alongside Birell they now pour an alcohol-free newcomer from Vinohradský pivovar.",lat:50.103903,lng:14.472795},
  {id:14,name:"Vršovická zahrada",district:"Vršovice",hood:"Praha 10",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 15–22\nÚterý 15–22\nStředa 15–22\nČtvrtek 15–22\nPátek 15–22\nSobota 15–22\nNeděle 15–22",address:"Francouzská 246/84, 101 00 Praha 10 – Vršovice",desc:"Venkovní bar ležící uprostřed komunitní zahrady přímo na zastávce MHD „Krymská“. Nabízí uvolněné prostředí pro relaxaci, sousedská setkávání, kulturní akce pod širým nebem a komunitní besedy či workshopy s tématikou udržitelnosti, doplněný o nealko nabídku z Vinohradského pivovaru včetně jejich Nealko 12 a Hazy Galaxy IPA.",descEn:"An outdoor bar set inside a community garden, right at the Krymská tram stop. It is a relaxed spot for neighbourhood gatherings, open-air cultural events and workshops on sustainability, with an alcohol-free range from Vinohradský pivovar including their Nealko 12 and Hazy Galaxy IPA.",lat:50.071759,lng:14.447624},
  {id:15,name:"Pivní jistota",district:"Dejvice",hood:"Praha 6",type:"Hospoda",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 15–23:59\nÚterý 15–23:59\nStředa 15–23:59\nČtvrtek 15–23:59\nPátek 15–23:59\nSobota 15–23:59\nNeděle 15–22",address:"Kyjevská 3, 160 00 Praha 6 – Dejvice",desc:"Moderní pivotéka a bar v Dejvicích jen pár kroků od \"kulaťáku\" a metra Dejvická zaměřený na řemeslná piva včetně nealka z českých i zahraničních pivovarů. Nabízí široký výběr na čepu i v lahvích s neustále se měnící nabídkou.",descEn:"A modern bottle shop and bar in Dejvice, a few steps from Vítězné náměstí and the metro, focused on craft beer — alcohol-free included — from Czech and foreign brewers. The selection on tap and in bottle changes constantly.",lat:50.098718,lng:14.398013},
  {id:16,name:"BeerGeek Bar",district:"Vinohrady",hood:"Praha 3",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 15–2\nÚterý 15–2\nStředa 15–2\nČtvrtek 15–2\nPátek 15–2\nSobota 15–2\nNeděle 15–2",address:"Vinohradská 988/62, 130 00 Praha 3 – Vinohrady",desc:"Legendární pivní bar na Vinohradech, který patří ke špičce pražské pivní scény s neustále se měnící nabídkou. Nabízí moderní industriální prostředí a obrovský výběr českých i světových speciálů, doplněný o stálou nabídku špičkových řemeslných nealko piv na čepu i v lahvích. Pod značku BeerGeek spadá i pivotéka, ležící v ulici Slavíkova, na opačné straně náměstí Jiřího z Poděbrad.",descEn:"A legendary beer bar in Vinohrady and one of the high points of the Prague beer scene, with a line-up that never stays still. Modern industrial surroundings, a vast range of Czech and international specials, and a permanent selection of top-tier alcohol-free craft beer on tap and in bottle. The BeerGeek name also covers a bottle shop on Slavíkova, on the far side of náměstí Jiřího z Poděbrad.",lat:50.077073,lng:14.449963},
  {id:17,name:"BeerGeek Pivotéka",district:"Žižkov",hood:"Praha 3",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ne",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–21\nÚterý 11–21\nStředa 11–21\nČtvrtek 11–21\nPátek 11–21\nSobota 11–21\nNeděle 15–21",address:"Slavíkova 1047/10, 130 00 Praha 3 – Žižkov",desc:"Vyhlášená žižkovská pivotéka v ulici Slavíkova, která nabízí jeden z největších výběrů řemeslných piv v Praze nedaleko stejnojmenného baru a možnost menšího posezení a ochutnávky. V regálech i chladicích boxech skrývá množství pečlivě vybraných lahví a plechovek od předních českých i světových minipivovarů, včetně bohatého zastoupení špičkových nealkoholických speciálů a ochotného personálu, který s výběrem vždy poradí.",descEn:"A renowned bottle shop on Slavíkova offering one of the largest craft beer selections in Prague, close to the bar of the same name, with room to sit down and taste. The shelves and fridges hold carefully chosen bottles and cans from leading Czech and international microbreweries, with strong representation of top alcohol-free specials and staff who are happy to steer you through it.",lat:50.079334,lng:14.448189},
  {id:18,name:"Skautský institut v Rybárně",district:"Malá Strana",hood:"Praha 1",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Čepované"},{name:"Maisel´s Weisse alkoholfrei",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 10–23\nÚterý 10–23\nStředa 10–23\nČtvrtek 10–23\nPátek 10–23\nSobota 10–23\nNeděle 10–23",address:"U Sovových mlýnů 134/1, 118 00 Praha 1 – Malá Strana",desc:"Komunitní centrum a bar v historickém domečku na břehu Vltavy na Kampě. Nabízí klidné kreativní prostředí pro odpočinek, kulturní akce a sousedská setkávání, doplněný o stálou nabídku poctivého nealka, denních polévek, salátů, sendvičů a dalších pochoutek k zakousnutí.",descEn:"A community centre and bar in a small historic building on the Vltava bank at Kampa. A calm, creative space for cultural events and neighbourhood gatherings, with a permanent alcohol-free offering alongside soups of the day, salads, sandwiches and other things to pick at.",lat:50.082914,lng:14.408065},
  {id:19,name:"Cafe club Míšeňská",district:"Malá Strana",hood:"Praha 1",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Chříč Balanc 0% IPA",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 10–0\nÚterý 10–0\nStředa 10–0\nČtvrtek 10–0\nPátek 10–0\nSobota 10–0\nNeděle 10–0",address:"Míšeňská 71/3, 118 00 Praha 1 – Malá Strana",desc:"Skrytý kavárenský bar v historickém domě s malebným dvorkem jen pár kroků od Karlova mostu. Nabízí jedinečnou, intimní atmosféru staré Prahy, skvělou kávu a večerní drinky, doplněný o pečlivě vybranou nabídku nealkoholických alternativ a drobných pochutin.",descEn:"A hidden café bar in a historic house with a picturesque courtyard, a few steps from Charles Bridge. The atmosphere is intimate and unmistakably old Prague — excellent coffee by day, drinks in the evening, and a carefully chosen range of alcohol-free alternatives and small bites.",lat:50.087644,lng:14.408038},
  {id:20,name:"Lasagneria Holešovice",district:"Holešovice",hood:"Praha 7",type:"Restaurace",serve:"Lahvové",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Kocour Tom Cat - Nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–21\nÚterý 11–21\nStředa 11–21\nČtvrtek 11–21\nPátek 11–21\nSobota 11–21\nNeděle Zavřeno",address:"Komunardů 26, 170 00 Praha 7 – Holešovice",desc:"Autentická italská lasagnerie v srdci Holešovic vsázející na poctivou ruční výrobu domácích lasagní. V moderním interiéru kousek od tramvaje nabízí masovou klasiku, prémiové verze s pistáciovým pestem i vegetariánské alternativy, doplněné o skvělé tiramisu a řemeslné nealko pivo z minipivovaru Kocour.",descEn:"An authentic Italian lasagneria in the heart of Holešovice, betting everything on lasagne made by hand. The modern interior sits just off the tram line and the menu runs from the meat classic to premium versions with pistachio pesto and vegetarian alternatives, rounded off with excellent tiramisu and craft alcohol-free beer from the Kocour microbrewery.",lat:50.103358,lng:14.450168},
  {id:21,name:"Pivní rozmanitost",district:"Žižkov",hood:"Praha 3",type:"Hospoda",serve:"Čepované",garden:"Ano",food:"Ne",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 15–22\nÚterý 15–22\nStředa 15–22\nČtvrtek 15–22\nPátek 14–23\nSobota 15–23\nNeděle Zavřeno",address:"Hartigova 1819, 130 00 Praha 3 – Žižkov",desc:"Tradiční žižkovský bar a skvěle zásobená pivotéka v jednom, ležící přímo u vozovny Žižkov. Nabízí příjemné, neformální prostředí s rotujícími pípami plnými českých i zahraničních řemeslných speciálů, které doplňují stovky druhů piv v lahvích a plechovkách z chladicích boxů k okamžitému osvěžení nebo odnesení domů.",descEn:"A traditional Žižkov bar and a well-stocked bottle shop in one, right by the Žižkov tram depot. The setting is easy and informal, the taps rotate through Czech and foreign craft specials, and the fridges hold hundreds of bottles and cans to drink in or take home.",lat:50.091520,lng:14.473659},
  {id:22,name:"Betlemska club",district:"Staré Město",hood:"Praha 1",type:"Bar",serve:"Lahvové",garden:"Ano",food:"Ne",craft:"Tradiční",beers:[{name:"Budvar nealko",cat:"Tradiční",serve:"Lahvové"},{name:"Maisel´s Weisse alkoholfrei",cat:"Tradiční",serve:"Lahvové"},{name:"Maisel´s Weisse alkoholfrei",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 11–22\nÚterý 11–22\nStředa 11–22\nČtvrtek 11–22\nPátek 11–22\nSobota 11–22\nNeděle 11–22",address:"Betlémské nám. 5a, 110 00 Praha 1 – Staré Město",desc:"Osobitá umělecká kavárna a bar od tvůrců holešovické Burzy #4, situovaná přímo v areálu Betlémské kaple. Nový multikulturní projekt v historickém centru Prahy spojuje skvělou kávu, večerní drinky a uvolněnou sousedskou atmosféru s pravidelnými jam sessions a komunitními akcemi s jedinečným géniem loci Starého Města.",descEn:"A distinctive art café and bar from the people behind Burza #4 in Holešovice, set inside the grounds of the Bethlehem Chapel. This new multicultural project in Prague's historic centre combines excellent coffee, evening drinks and an easy neighbourhood atmosphere with regular jam sessions and community events in a setting the Old Town has made its own.",lat:50.084483,lng:14.417897},
  {id:23,name:"Beer Bar Manifesto",district:"Smíchov",hood:"Praha 5",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Birell",cat:"Birell",serve:"Čepované"},{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–22\nÚterý 11–22\nStředa 11–22\nČtvrtek 11–0\nPátek 11–0\nSobota 11–0\nNeděle 11–22",address:"Ostrovského 34, 150 00 Praha 5 – Smíchov",desc:"Moderní pivní bar v areálu Manifesto Marketu na Andělu, který nabízí posezení pod širým nebem v živém designovém prostředí populárního food marketu. Na čepu najdete skvěle ošetřený Birell a v chladicích boxech nekompromisní řemeslný nealko speciál v podobě lahvové IPA Krystus z řemeslného pivovaru Clock, což z baru dělá ideální zastávku pro milovníky dobrého piva i bez kapky alkoholu.",descEn:"A modern beer bar inside the Manifesto Market at Anděl, with open-air seating in the lively design surroundings of the popular food market. The tap pours well-kept Birell, while the fridges hold an uncompromising alcohol-free craft special in the form of bottled IPA Krystus from the Clock brewery — which makes this a reliable stop for anyone who loves good beer without the alcohol.",lat:50.069299,lng:14.404127},
  {id:24,name:"Bullerbyn",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 14–1\nÚterý 14–1\nStředa 14–1\nČtvrtek 14–1\nPátek 14–1\nSobota 11–1\nNeděle 11–0",address:"Chodská 17, 120 00 Praha 2 – Vinohrady",desc:"Stylový vinohradský bar s uvolněnou atmosférou, kde přes den servírují menší stálé menu a večer skvělé drobnosti k pivu. Interiér nabízí příjemné prostředí, které doplňuje pečlivě ošetřené řemeslné pivo na čepu, včetně měnících se nealkoholických speciálů podle aktuální nabídky.",descEn:"A stylish Vinohrady bar with a relaxed feel, serving a small regular menu during the day and good things to go with beer in the evening. The interior is comfortable and the draught craft beer is kept with care, including alcohol-free specials that change with what is available.",lat:50.074567,lng:14.445674},
  {id:25,name:"Bar Hvězda",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Tradiční",beers:[{name:"Bernard Švestka Nealko",cat:"Tradiční",serve:"Čepované"},{name:"Bakalář Nealko",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 10–0:30\nÚterý 10–0:30\nStředa 10–0:30\nČtvrtek 10–0:30\nPátek 10–0:30\nSobota 10–0:30\nNeděle 10–0:30",address:"Polská 1, 120 00 Praha 2 – Vinohrady",desc:"Stylový vinohradský bar v Riegrových sadech s uvolněnou sousedskou atmosférou a moderním interiérem, který v létě doplňuje velmi příjemná terasa. Kromě skvěle ošetřeného piva, a to včetně nealko variant, nabízejí také menší stálou nabídku teplého jídla a skvělých sendvičů k zakousnutí.",descEn:"A stylish Vinohrady bar in Riegrovy sady with an easy neighbourhood atmosphere and a modern interior, extended in summer by a very pleasant terrace. Beyond well-kept beer — alcohol-free versions included — they serve a small regular menu of hot food and excellent sandwiches.",lat:50.078862,lng:14.442026},
  {id:26,name:"Unijazz",district:"Žižkov",hood:"Praha 3",type:"Bar",serve:"Lahvové",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Lahvové"},{name:"Birell",cat:"Birell",serve:"Lahvové"},{name:"Bernard",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 14–23\nÚterý 14–23\nStředa 14–23\nČtvrtek 14–23\nPátek 14–23\nSobota 16–0\nNeděle Zavřeno",address:"Husitská 22, 130 00 Praha 3 – Žižkov",desc:"Unijazz na Žižkově je legendární kulturní a společenské centrum s nezaměnitelnou, uvolněnou atmosférou a útulným interiérem. Jako rychlé jídlo k zakousnutí nabízejí skvělé sendviče a čerstvé bagety. V nabídce nápojů navíc najdete široký výběr lahvových nealko variant, kterým dominuje famózní nealkoholický speciál Clock Krystus.",descEn:"Unijazz in Žižkov is a legendary cultural and social centre with an unmistakable relaxed atmosphere and a cosy interior. For something quick to eat there are excellent sandwiches and fresh baguettes. The drinks list carries a wide choice of bottled alcohol-free beers, led by the remarkable Clock Krystus.",lat:50.087186,lng:14.441133},
  {id:27,name:"Lampičky",district:"Žižkov",hood:"Praha 3",type:"Restaurace",serve:"Lahvové",garden:"Ano",food:"Ano",craft:"Tradiční",beers:[{name:"Krušovice nealko",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 11–23\nÚterý 11–23\nStředa 11–23\nČtvrtek 11–23\nPátek 11–23\nSobota 11–23\nNeděle 11–23",address:"Hartigova 1886/173, 130 00 Praha 3 – Žižkov",desc:"Příjemná restaurace na Žižkově, kterou najdete v těsné blízkosti Jarovských kolejí, populární především pro své skvělé a šťavnaté burgry. K dobrému jídlu zde navíc jako osvěžující nealko variantu nabízejí lahvové nealko Krušovice.",descEn:"A welcoming restaurant in Žižkov, right by the Jarov student halls, known above all for its excellent juicy burgers. Bottled alcohol-free Krušovice is on hand as a refreshing option alongside the food.",lat:50.092428,lng:14.481047},
  {id:28,name:"Přístav 18600",district:"Karlín",hood:"Praha 8",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ne",craft:"Birell",beers:[{name:"Birell",cat:"Birell",serve:"Čepované"},{name:"Birell",cat:"Birell",serve:"Lahvové"}],hours:"Pondělí 11–23\nÚterý 11–23\nStředa 11–23\nČtvrtek 11–23\nPátek 11–23\nSobota 10–23\nNeděle 10–23",address:"Rohanský ostrov 8, 186 00 Praha 8 – Karlín",desc:"Přístav 18600 v Karlíně je jedinečný open-air prostor na břehu Vltavy, který kombinuje uvolněnou atmosféru letního kulturního centra s oázou klidu uprostřed města. Tento oblíbený plácek pod širým nebem je ideálním místem pro setkání s přáteli, drink po práci nebo odpočinek u řeky. Vedle klasického piva a osvěžujících drinků mají na čepu také točené nealko v podobě Birellu. Vlastní kuchyni sice nemají, ale hlad zde spolehlivě zaženou foodtrucky, které v areálu nepravidelně fungují, nebo nabízejí možnost využití venkovních grillů.",descEn:"Přístav 18600 in Karlín is a one-off open-air space on the Vltava bank, combining the feel of a summer cultural centre with a pocket of calm in the middle of the city. This popular patch of open ground suits meeting friends, an after-work drink or simply sitting by the river. Alongside regular beer and refreshing drinks, there is alcohol-free Birell on tap. There is no kitchen of its own, but food trucks turn up in the grounds and outdoor grills are available.",lat:50.095823,lng:14.447490},
  {id:29,name:"Cafe Barrandé",district:"Žižkov",hood:"Praha 3",type:"Hospoda",serve:"Lahvové",garden:"Ano",food:"Drobné občerstvení",craft:"Tradiční",beers:[{name:"Bakalář Nealko",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí Zavřeno\nÚterý 16–22\nStředa 16–22\nČtvrtek 16–22\nPátek 16–22\nSobota Zavřeno\nNeděle Zavřeno",address:"Ježkova 8, 130 00 Praha 3 – Žižkov",desc:"Café Barrande na Žižkově je kouzelný rodinný bar s nostalgickou atmosférou, dobovým interiérem a swingovou hudbou. Podnik pravidelně ožívá kulturními akcemi a v létě láká na klidnou zahrádku ve vnitrobloku. Vedle poctivých koktejlů a kvalitních vín nabízí jako nealko variantu také lahvového Bakaláře.",descEn:"Café Barrande in Žižkov is a charming family-run bar with a nostalgic atmosphere, period interior and swing on the stereo. Cultural events come round regularly and summer brings a quiet garden in the courtyard. Alongside well-made cocktails and good wine, bottled Bakalář covers the alcohol-free option.",lat:50.081878,lng:14.446070},
  {id:30,name:"Čep&Pec",district:"Nusle",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 15–0\nÚterý 15–0\nStředa 15–0\nČtvrtek 15–0\nPátek 15–0\nSobota 15–0\nNeděle 15–22",address:"Svatoplukova 528, 128 00 Praha 2 – Nusle",desc:"Čep&Pec v Nuslích je příjemný rodinný podnik, který originálně spojuje výčep a řemeslnou pekárnu. V autentické atmosféře si zde vychutnáte pestrou škálu piv z malých pivovarů, čerstvé pečivo a poctivé jídlo připravované výhradně z lokálních surovin od místních zemědělců. K občerstvení můžete ochutnat také řemeslné nealkoholické speciály.",descEn:"Čep&Pec in Nusle is a welcoming family-run place that pairs a taproom with a craft bakery. The atmosphere is genuine, the beer comes from small breweries, and the bread and food are made entirely from local ingredients sourced from nearby farmers. Craft alcohol-free specials are part of the range.",lat:50.065814,lng:14.429984},
  {id:31,name:"Břevnovský klášterní pivovar",district:"Břevnov",hood:"Praha 6",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Benedict nealko",cat:"Craft",serve:"Čepované"},{name:"Benedict nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11:30–23\nÚterý 11:30–23\nStředa 11:30–23\nČtvrtek 11:30–23\nPátek 11:30–23\nSobota 11:30–23\nNeděle 11:30–23",address:"Markétská 1/28, 169 00 Praha 6 – Břevnov",desc:"Břevnovský klášter, nejstarší mužský klášter v Čechách, je již od svého vzniku v roce 993 úzce spjatý s výrobou piva. Ke klášteru se totiž váže vůbec první písemná zmínka o vaření piva na českém území. Pivovar zde fungoval s několika přestávkami až do roku 1889. Na tuto dlouhou tradici navazuje nový pivovar vybudovaný v roce 2011, který kromě poctivých alkoholických ležáků a speciálů vaří také své vlastní vynikající nealkoholické pivo Nealko Benedict.",descEn:"Břevnov Monastery, the oldest men's monastery in Bohemia, has been tied to brewing since its founding in 993 — the first written mention of beer brewing on Czech soil relates to this site. A brewery operated here, with interruptions, until 1889. The new brewery built in 2011 continues that line, producing honest lagers and specials alongside its own excellent alcohol-free beer, Nealko Benedict.",lat:50.083777,lng:14.356343},
  {id:32,name:"Krčma u Sváry",district:"Hodkovičky",hood:"Praha 4",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Tradiční",beers:[{name:"Lobkowicz nealko",cat:"Tradiční",serve:"Čepované"}],hours:"Pondělí Zavřeno\nÚterý Zavřeno\nStředa 15–21\nČtvrtek 15–21\nPátek 15–21\nSobota 12–22\nNeděle 12–20",address:"Lodnická 1, 147 00 Praha 4 – Hodkovičky",desc:"Neformální venkovní okénko s přilehlým posezením v Hodkovičkách, které láká kolemjdoucí i cyklisty na orosené pivo. K pití nabízí klasické hospodské chuťovky k zakousnutí. Ideální zastávka pro letní osvěžení během procházky podél Vltavy, kde si na své přijdou i řidiči či sportovci – na čepu je pro ně připraveno osvěžující nealkoholické pivo Lobkowicz.",descEn:"An informal outdoor serving hatch with seating in Hodkovičky, pulling in passers-by and cyclists for a cold beer. Classic pub snacks are on hand. It makes an ideal summer stop on a walk along the Vltava, and drivers and cyclists are not left out — alcohol-free Lobkowicz is on tap.",lat:50.023821,lng:14.398109},
  {id:33,name:"Avoid Floating Gallery",district:"Nové Město",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–0\nÚterý 16–0\nStředa 16–0\nČtvrtek 16–0\nPátek 16–0\nSobota 14–0\nNeděle 14–0",address:"Rašínovo nábř. 2, 120 00 Praha 2 – Nové Město",desc:"Unikátní plovoucí bar a galerie na pražské Náplavce, kde se skvěle kloubí kulturní zážitky s relaxací na vlnách. Kromě koncertů a výstav nabízí pravidelně se střídající craftová piva z malých pivovarů, která si nejlépe vychutnáte na otevřené palubě při západu slunce nad Hradčany. Vedle alkoholických speciálů je na čepu pokaždé připravena také plnohodnotná řemeslná nealko varianta podle aktuální rotující nabídky.",descEn:"A one-off floating bar and gallery on Prague's Náplavka embankment, where cultural events and time on the water go together neatly. Beyond concerts and exhibitions there are rotating craft beers from small breweries, best enjoyed on the open deck as the sun sets behind the Castle. A full craft alcohol-free option is always on tap as part of the rotation.",lat:50.067714,lng:14.414487},
  {id:34,name:"Barcelounoc",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ne",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 18–2\nÚterý 18–2\nStředa 18–2\nČtvrtek 18–2\nPátek 18–3\nSobota 18–3\nNeděle 18–2",address:"J. Masaryka 265/58, 120 00 Praha 2 – Vinohrady",desc:"Živý vinohradský bar s uvolněnou noční atmosférou, kam můžete zajít na skvělý drink i poctivé lokální pivo. Pro ty, kteří dávají přednost nealkoholické variantě a chtějí si užít večer naplno, mají na čepu vedle vždy výbornou řemeslnou nulu Vinohradská 12 nealko z nedalekého Vinohradského pivovaru.",descEn:"A lively Vinohrady bar with a relaxed late-night feel, good for a well-made drink or honest local beer. For anyone choosing the alcohol-free route and still wanting the full evening, there is excellent Vinohradská 12 nealko on tap from the nearby Vinohradský pivovar.",lat:50.072778,lng:14.441478},
  {id:35,name:"Dish Belgická",district:"Vinohrady",hood:"Praha 2",type:"Restaurace",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Tradiční",beers:[{name:"Maisel´s Weisse alkoholfrei",cat:"Tradiční",serve:"Čepované"}],hours:"Pondělí 11–23\nÚterý 11–23\nStředa 11–23\nČtvrtek 11–23\nPátek 11–23\nSobota 11–23\nNeděle 12–22",address:"Belgická 335/26, 120 00 Praha 2 – Vinohrady",desc:"Legendární pražská burgrárna vyhlášené svými vyladěnými gurmánskými burgery a precizním servisem. K těžšímu šťavnatému masu zde geniálně pasuje čepované nealkoholické pšeničné pivo Maisel's Weisse, které celé jídlo skvěle osvěží, odlehčí a představuje ideální řemeslnou nealko alternativu k alkoholickým ležákům na lístku.",descEn:"A legendary Prague burger joint, known for finely tuned gourmet burgers and precise service. The rich, juicy meat pairs brilliantly with draught alcohol-free Maisel's Weisse, which lifts and lightens the whole plate and stands as a proper craft alternative to the lagers on the list.",lat:50.073056,lng:14.436189},
  {id:36,name:"Bistro Karel",district:"Troja",hood:"Praha 7",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Čepované"},{name:"Clock Nana nealko sour ale",cat:"Craft",serve:"Čepované"}],hours:"Pondělí Zavřeno\nÚterý 9–22\nStředa 9–22\nČtvrtek 9–22\nPátek 9–22\nSobota 9–22\nNeděle 9–20",address:"U Trojského zámku 2/6, 171 00 Praha 7 – Troja",desc:"Stylové a moderní bistro situované v bezprostřední blízkosti Trojského zámku, obklopené zelení. Je to ideální oáza pro rodiny i cyklisty hledající kvalitní gastronomii, kde navíc maximálně myslí na milovníky řemeslného piva bez alkoholu. Na pípě totiž vedle běžné nabídky střídají špičkové nealko speciály od pivovaru Clock – osvěžující hořkou nealko IPA Krystus a ovocnou, lehkou nealko sour ale Clock Nana.",descEn:"A stylish modern bistro right by Troja Château, surrounded by greenery. It makes an ideal stop for families and cyclists after good food, and the thinking about alcohol-free craft beer here goes further than most. Alongside the regular line-up, the taps rotate top specials from the Clock brewery — the bracingly bitter alcohol-free IPA Krystus and the light, fruity alcohol-free sour ale Clock Nana.",lat:50.114954,lng:14.411343},
  {id:37,name:"Vinohradský pivovar",district:"Vinohrady",hood:"Praha 10",type:"Hospoda",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Čepované"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–0\nÚterý 11–0\nStředa 11–0\nČtvrtek 11–0\nPátek 11–0\nSobota 11–0\nNeděle 11–22",address:"Korunní 90, 101 00 Praha 10 – Vinohrady",desc:"Tradiční městský řemeslný pivovar s prostorným, vzdušným interiérem a skvělou kuchyní. Jsou průkopníky v tom, že i nealkoholické pivo berou jako plnohodnotný gastronomický zážitek. Vedle svých klasických ležáků tak hrdě čepují vlastní Vinohradskou 12 nealko a především vyhlášenou, chmelově intenzivní nealko nefiltrovanou IPA Vinohradská Hazy Galaxy, která svou vůní směle konkuruje alkoholickým speciálům.",descEn:"A traditional urban craft brewery with a spacious, airy interior and an excellent kitchen. They were among the first to treat alcohol-free beer as a full gastronomic experience in its own right. Alongside their classic lagers they proudly pour their own Vinohradská 12 nealko and, above all, the celebrated hop-forward unfiltered alcohol-free IPA Vinohradská Hazy Galaxy, whose aroma holds its own against anything with alcohol in it.",lat:50.075298,lng:14.457606},
  {id:38,name:"Beer Time",district:"Smíchov",hood:"Praha 5",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11–23:30\nÚterý 11–23:30\nStředa 11–23:30\nČtvrtek 11–1\nPátek 11–1\nSobota 12–23:30\nNeděle 12–22",address:"Nádražní 61/116, 150 00 Praha 5 – Smíchov",desc:"Moderní pivní ráj na Smíchově, který láká na obrovské množství píp a neustále se obměňující nabídku piv z malých pivovarů. Zkrátka zde nepřijdou ani ti, co zrovna řídí nebo nechtějí alkohol – vedle desítek klasických craftů na čepu stabilně najdete 1 až 2 druhy poctivých, čepovaných řemeslných nealko piv podle aktuální denní nabídky.",descEn:"A modern beer paradise in Smíchov, drawing people in with a huge bank of taps and a line-up from small breweries that never stops changing. Anyone driving or simply not drinking is well looked after — alongside dozens of regular craft beers on tap there are reliably one or two honest draught craft alcohol-free beers, depending on the day.",lat:50.071276,lng:14.404765},
  {id:39,name:"BIG SMOKERS",district:"Holešovice",hood:"Praha 7",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí Zavřeno\nÚterý Zavřeno\nStředa 11:30–22\nČtvrtek 11:30–22\nPátek 11:30–22\nSobota 11:30–22\nNeděle 11:30–20",address:"Dělnická 643/40, 170 00 Praha 7 – Holešovice",desc:"Autentický americký BBQ smokehouse v Holešovicích, kde hraje hlavní roli maso pomalu uzené na dřevě. Drsnou a poctivou atmosféru podniku a plnou chuť barbecue skvěle doplňuje nejen alkoholické řemeslné pivo, ale také jeho bezchybná nealko varianta – hořká, výborně vychlazená čepovaná nealko IPA Krystus od řemeslného pivovaru Clock.",descEn:"An authentic American BBQ smokehouse in Holešovice, where meat smoked slowly over wood takes the lead. The rough, honest atmosphere and the full flavour of the barbecue are matched not only by craft beer but by its faultless alcohol-free counterpart — the bitter, properly chilled draught alcohol-free IPA Krystus from the Clock brewery.",lat:50.103019,lng:14.450957},
  {id:40,name:"Čtyrka",district:"Holešovice",hood:"Praha 7",type:"Hospoda",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Čepované"},{name:"Primátor Tchyně India Pale Lager nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11–23:30\nÚterý 11–23:30\nStředa 11–23:30\nČtvrtek 11–23:30\nPátek 11–23:30\nSobota 12–22:30\nNeděle 17–22",address:"Komunardů 1001/30, 170 00 Praha 7 – Holešovice",desc:"Oblíbená holešovická hospoda s uvolněným švihem a moderním interiérem, kam lidé rádi chodí na dobrý oběd i večerní posezení s přáteli. Na čepu pravidelně rotují skvělá piva a jejich nabídka nealko craftu snese ta nejpřísnější měřítka – k alkoholickým kouskům tu jako plnohodnotnou alternativu nabízí čepovanou nealko IPA Krystus od Clocka nebo chuťově výraznou nealko Tchýni od Primátora.",descEn:"A well-liked Holešovice pub with an easy swing to it and a modern interior, where people come for a good lunch as much as an evening with friends. The taps rotate excellent beers and the alcohol-free craft selection stands up to the strictest scrutiny — draught alcohol-free IPA Krystus from Clock or the boldly flavoured alcohol-free Tchýně from Primátor serve as full alternatives to anything with alcohol.",lat:50.103732,lng:14.450247},
  {id:41,name:"malý pivo",district:"Vinohrady",hood:"Praha 10",type:"Bar",serve:"Lahvové",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Podle aktuální nabídky: Clock, Zichovec, Sibeeria a další",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 16–23\nÚterý 16–23\nStředa 16–23\nČtvrtek 16–23\nPátek 16–23\nSobota 16–23\nNeděle 16–23",address:"Mrštíkova 2450/1, 100 00 Praha 10 – Vinohrady",desc:"Útulná pivotéka s nesmírně přátelským a edukovaným personálem, který vám s láskou pomůže vybrat to pravé. Vedle klasických alkoholických speciálů disponují lednicí napěchovanou těmi nejlepšími českými i zahraničními řemeslnými nealko pivy v plechovkách od špičkových pivovarů jako Clock, Zichovec či Sibeeria, takže můžete bez obav ochutnávat klidně celý večer.",descEn:"A snug bottle shop with exceptionally friendly, well-informed staff who will happily help you find the right thing. Alongside the usual specials, the fridge is packed with the best Czech and international craft alcohol-free beers in cans, from brewers like Clock, Zichovec and Sibeeria — enough to taste your way through an entire evening without worry.",lat:50.072658,lng:14.485608},
  {id:42,name:"Mrtvá ryba",district:"Nové Město",hood:"Praha 2",type:"Hospoda",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 9–0:30\nÚterý 9–0:30\nStředa 9–0:30\nČtvrtek 9–0:30\nPátek 11–0:30\nSobota Zavřeno\nNeděle 18–23",address:"Benátská 4/1965, 128 00 Praha 2 – Nové Město",desc:"Legendární studentský podnik skrytý v Albertově, který slouží jako oblíbené útočiště nejen pro studenty přilehlé Přírodovědecké fakulty UK. Vyznačuje se domáckou, lehce punkovou atmosférou, skvělou zahrádkou ve dvoře a překvapivě dobrou nabídkou nápojů. K točeným alkoholickým klasikám tu na čepu pro abstinenty a řidiče vždy běží i výborná craftová nealko piva podle aktuální sezónní nabídky.",descEn:"A legendary student haunt tucked away in Albertov, long serving as a refuge for students of the nearby Faculty of Science and anyone else who finds it. The atmosphere is homely with a faintly punk edge, the courtyard garden is excellent, and the drinks list is better than it has any right to be. Alongside the draught classics there is always good craft alcohol-free beer on tap, depending on the season.",lat:50.072451,lng:14.423056},
  {id:43,name:"Burza 4",district:"Holešovice",hood:"Praha 7",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Craft, nealko 12 Vinohradská",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–0\nÚterý 16–0\nStředa 16–2\nČtvrtek 15–2\nPátek 15–3\nSobota 15–3\nNeděle 16–0",address:"Bubenské nábř. 306/13, 170 00 Praha 7 – Holešovice",desc:"Živý a stylový industriální bar situovaný přímo v srdci Pražské tržnice v Holešovicích. Tento vyhlášený \"hipster\" spot nabízí skvělou venkovní atmosféru, kulturní akce a k široké škále alkoholických drinků a piv nabízí na osvěžení výtečnou řemeslnou nealkoholickou dvanáctku z Vinohradského pivovaru přímo na čepu.",descEn:"A lively industrial bar in the heart of the Prague Market Halls in Holešovice. This well-known hipster spot offers a great outdoor atmosphere and regular cultural events, and alongside the wide range of drinks and beers it pours an excellent craft alcohol-free twelve from Vinohradský pivovar straight from the tap.",lat:50.098408,lng:14.445307},
  {id:44,name:"Café Sladkovsky",district:"Vršovice",hood:"Praha 10",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–0\nÚterý 16–0\nStředa 16–0\nČtvrtek 16–0\nPátek 16–0\nSobota 16–0\nNeděle 16–0",address:"Sevastopolská 17, 101 00 Praha 10 – Vršovice",desc:"Café Sladkovský v srdci vyhlášené vršovické čtvrti kolem Krymské ulice je ikonický bar s osobitou, lehce bohémskou atmosférou a skvělou komunitní energií. K příjemnému posezení, dobrému jídlu a široké škále drinků nabízí milovníkům nealkoholického piva hned dvě skvělé varianty přímo na čepu z nedalekého Vinohradského pivovaru – osvěžující Vinohradskou nealko 12 a chuťově výraznou, chmelovou nealko IPA Hazy Galaxy.",descEn:"Café Sladkovský, at the centre of the Krymská neighbourhood in Vršovice, is an iconic bar with a distinctive, faintly bohemian atmosphere and real community energy. Alongside comfortable seating, good food and a wide range of drinks, it offers two excellent alcohol-free beers on tap from the nearby Vinohradský pivovar — the refreshing Vinohradská nealko 12 and the bold, hoppy alcohol-free IPA Hazy Galaxy.",lat:50.071039,lng:14.449059},
  {id:45,name:"Waid",district:"Nové Město",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 12–1\nÚterý 12–1\nStředa 12–1\nČtvrtek 12–1\nPátek 12–1\nSobota 12–1\nNeděle 12–23",address:"Lublaňská 57, 120 00 Praha 2 – Nové Město",desc:"Waid je oblíbený a neformální bar situovaný na Novém Městě jen kousek od rušného uzlu I. P. Pavlova, který láká na uvolněnou atmosféru i velkou, příjemnou zahrádku skrytou ve vnitrobloku. Ke klasickým alkoholickým drinkům a pivům zde nabízí pestrou rotující nabídku řemeslných nealko speciálů, takže si tu na své přijdou všichni pivaři – vychutnat si můžete například vynikající nealkoholický Ale Balanc od pivovaru Chříč a další skvělé craftové kousky podle aktuálního výběru.",descEn:"Waid is a popular, informal bar in Nové Město just off the busy I. P. Pavlova junction, drawing people in with a relaxed feel and a large, comfortable garden hidden in the courtyard. Alongside the usual drinks and beers there is a varied rotating selection of craft alcohol-free specials, so every beer drinker is covered — you might find the excellent alcohol-free Ale Balanc from the Chříč brewery among other craft picks, depending on what is on.",lat:50.074587,lng:14.431132},
  {id:46,name:"SKÔ",district:"Holešovice",hood:"Praha 7",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"NILIO ZERO POWER Pale Ale",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 17–23\nÚterý 11:30–14:30 17–23\nStředa 11:30–14:30 17–23\nČtvrtek 11:30–14:30 17–23\nPátek 11:30–14:30 17–23\nSobota 11:30–14:30 17–23\nNeděle 11:30–17",address:"Hala 28, Bubenské nábř. 306/13, 170 00 Praha 7 – Holešovice",desc:"SKO je vyhlášená slovenská restaurace ze sítě Ambiente situovaná přímo v prostředí Holešovické tržnice, která přináší poctivou tradiční i moderní gastronomii s vřelou a pohostinnou atmosférou. K výborným specialitám slovenské kuchyně a široké nabídce nápojů nabízí jako skvělou nealkoholickou alternativu řemeslný speciál NILIO Zero Power Pale Ale z mezinárodně oceňovaného slovenského nealko pivovaru NILIO, který potěší plnou chutí a bohatým chmelovým aroma.",descEn:"SKÔ is a well-regarded Slovak restaurant from the Ambiente group, set inside the Holešovice Market Halls, serving traditional and modern cooking in a warm, hospitable setting. Alongside the Slovak specialities and a broad drinks list, the alcohol-free option is the craft special NILIO Zero Power Pale Ale from the internationally awarded Slovak alcohol-free brewery NILIO — full in flavour with a rich hop aroma.",lat:50.100294,lng:14.445882},
  {id:47,name:"Malešický mikropivovar",district:"Malešice",hood:"Praha 10",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11–23\nÚterý 11–23\nStředa 11–23\nČtvrtek 11–23\nPátek 11–23\nSobota 11–23\nNeděle 12–22",address:"Malešická 126/50, 108 00 Praha 10 – Malešice",desc:"Malešický mikropivovar v Malešicích je oblíbený pivní gastronomický prostor s velkou zahrádkou, pestrou nabídkou jídel a skvěle ošetřeným pivem na čepu. Vedle tradičních alkoholických speciálů a ležáků nabízí milovníkům chmelových chutí také skvělou řemeslnou alternativu v podobě čepované nealko IPA Krystus od vyhlášeného pivovaru Clock.",descEn:"Malešický mikropivovar is a popular brewery restaurant with a large garden, a varied food menu and well-kept beer on tap. Alongside the traditional lagers and specials, anyone after hop character without the alcohol will find an excellent craft alternative in the draught alcohol-free IPA Krystus from the renowned Clock brewery.",lat:50.084660,lng:14.507609},
  {id:48,name:"Vinohradský parlament",district:"Vinohrady",hood:"Praha 2",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Tradiční",beers:[{name:"Birell",cat:"Tradiční",serve:"Čepované"}],hours:"Pondělí 10:45–23\nÚterý 10:45–23:30\nStředa 10:45–23:30\nČtvrtek 10:45–0\nPátek 10:45–0\nSobota 11:30–0\nNeděle 11:30–23",address:"Korunní 1, 120 00 Praha 2 – Vinohrady",desc:"Vinohradský parlament na Náměstí Míru je rušná a vyhlášená konceptuální restaurace zaměřená na moderní českou gastronomii, která se pyšní i vlastní „knedlíkárnou“ se samostatnou pestrou nabídkou tradičních i netradičních knedlíků. K vydatným pokrmům zde vedle klasických alkoholických ležáků čepují také osvěžující točený Birell, který představuje spolehlivou nealkoholickou alternativu ke gastronomickému zážitku.",descEn:"Vinohradský parlament on Náměstí Míru is a busy, well-known concept restaurant built around modern Czech cooking, with its own dumpling kitchen turning out a varied range of traditional and rather less traditional dumplings. Alongside the lagers, refreshing draught Birell serves as a reliable alcohol-free companion to the food.",lat:50.075424,lng:14.438301},
  {id:49,name:"Mama Shelter",district:"Holešovice",hood:"Praha 7",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11:30–23\nÚterý 11:30–23\nStředa 11:30–23\nČtvrtek 11:30–23\nPátek 11:30–0\nSobota 11:30–0\nNeděle 11:30–22",address:"Veletržní 1502/20, 170 00 Praha 7 – Holešovice",desc:"Mama Shelter Restaurant v Holešovicích, situovaná v ikonickém hotelu Mama Shelter, je stylový, hravý a designově nepřehlédnutelný prostor známý mimo jiné pro své vyhlášené nedělní all-you-can-eat Mama Brunche. K poctivé gastronomii a neformální atmosféře zde vedle klasických piv nabízí přímo na čepu také skvělou řemeslnou nealkoholickou dvanáctku z Vinohradského pivovaru, která představuje perfektní a plnohodnotné osvěžení k jídlu i nedělnímu lenošení.",descEn:"Mama Shelter Restaurant in Holešovice, inside the hotel of the same name, is a stylish, playful and visually unmissable space, known among other things for its Sunday all-you-can-eat Mama Brunch. Alongside honest cooking, an informal atmosphere and the usual beers, it pours an excellent craft alcohol-free twelve from Vinohradský pivovar — a proper match for the food and for a slow Sunday.",lat:50.102370,lng:14.432191},
  {id:50,name:"Hospůdka Zlý Časy",district:"Nusle",hood:"Praha 4",type:"Hospoda",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Clock Krystus nealko IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 15–2\nÚterý 15–2\nStředa 15–2\nČtvrtek 15–2\nPátek 15–2\nSobota 17–2\nNeděle 17–23:30",address:"Čestmírova 390, 140 00 Praha 4 – Nusle",desc:"Hospůdka Zlý časy v Nuslích je legendární pražský pivní svatostánek s obrovskou nabídkou čepovaných speciálů z malých i řemeslných pivovarů a poctivou hospodskou atmosférou. K pití zde servírují i poctivé pivní speciality – od šťavnatých burgerů, langošů a žebírek až po křupavá křidélka, smažák či čerstvý tatarák. Pro ty, kteří hledají plnou chmelovou chuť bez alkoholu, nabízejí na čepu skvělou řemeslnou nealko IPA Krystus od vyhlášeného pivovaru Clock.",descEn:"Hospůdka Zlý časy in Nusle is a legendary Prague beer shrine with an enormous range of draught specials from small and craft breweries, and a thoroughly pub atmosphere. The food holds its own — juicy burgers, langoše, ribs, crisp wings, fried cheese and fresh steak tartare. For full hop flavour without the alcohol, there is the craft alcohol-free IPA Krystus from the Clock brewery on tap.",lat:50.064306,lng:14.442029},
  {id:51,name:"Sober CafeBar",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ne",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Speciály (dle nabídky)",cat:"Craft",serve:"Čepované"},{name:"Bernard nealko",cat:"Craft",serve:"Čepované"},{name:"Bernard nealko - ochucený",cat:"Craft",serve:"Čepované"},{name:"Maisel´s Weisse alkoholfrei",cat:"Craft",serve:"Lahvové"},{name:"BRLO | Nealkoholické pivo naked",cat:"Craft",serve:"Lahvové"},{name:"Elektrárna Proovan IPA",cat:"Craft",serve:"Lahvové"},{name:"Sibeeria Hop Water",cat:"Craft",serve:"Lahvové"},{name:"NILIO ZERO POWER Pale Ale",cat:"Craft",serve:"Lahvové"},{name:"NILIO Great Warrior",cat:"Craft",serve:"Lahvové"},{name:"NILIO Yuzu Samurai",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 10:00–22:00\nÚterý 10:00–22:00\nStředa 10:00–22:00\nČtvrtek 10:00–22:00\nPátek 10:00–22:00\nSobota 10:00–22:00\nNeděle 10:00–22:00",address:"Italská 3, 120 00 Praha 2 – Vinohrady",desc:"Sober CafeBar kousek od Náměstí Míru je nově vzniklý koncept komplet nealkoholického baru, který se specializuje především na nealko drinky a moderní mixologii. V uvolněné atmosféře zde vedle vyladěných koktejlů nabízí i pestrou a širokou škálu nealko piv na čepu i v láhvích – od značek jako Bernard, NILIO, BRLO, Elektrárna, Sibeeria nebo Maisel. Představuje tak ideální místo pro každého, kdo si chce užít plnohodnotný barový zážitek a skvělé chutě zcela bez alkoholu.",descEn:"Sober CafeBar, a short walk from Náměstí Míru, is a newly opened fully alcohol-free bar specialising in alcohol-free drinks and modern mixology. Alongside finely tuned cocktails, the relaxed room offers a wide range of alcohol-free beers on tap and in bottle, from brands including Bernard, NILIO, BRLO, Elektrárna, Sibeeria and Maisel. It makes an ideal spot for anyone wanting the full bar experience and genuine flavour with no alcohol at all.",lat:50.076450,lng:14.434991},
  {id:52,name:"poco.",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ne",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí Zavřeno\nÚterý 18–1\nStředa 18–1\nČtvrtek 18–1\nPátek 18–1\nSobota 18–1\nNeděle Zavřeno",address:"Mánesova 1175/48, 120 00 Praha 2 – Vinohrady",desc:"poco. bar na Vinohradech je útulný a stylový bar a galerie s příjemnou sousedskou atmosférou, který spojuje lásku k umění s večerním drinkem. Na čepu servíruje poctivou nealkoholickou dvanáctku z nedalekého Vinohradského pivovaru, která nabízí plnou chmelovou chuť a skvělé osvěžení zcela bez alkoholu.",descEn:"poco. in Vinohrady is a snug, stylish bar and gallery with a pleasant neighbourhood feel, joining a love of art to an evening drink. The tap pours the honest alcohol-free twelve from the nearby Vinohradský pivovar — full hop flavour and proper refreshment with no alcohol involved.",lat:50.077733,lng:14.441455},
  {id:53,name:"Kolektor",district:"Holešovice",hood:"Praha 7",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Zichovec nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 9–22\nÚterý 9–22\nStředa 9–0\nČtvrtek 9–0\nPátek 9–0\nSobota 9–0\nNeděle 9–22",address:"Dukelských Hrdinů 530/47, 170 00 Praha 7 – Holešovice",desc:"Kolektor v Holešovicích, situovaný přímo v budově Veletržního paláce, je stylová kavárna, bar a kulturní prostor s jedinečnou industriální atmosférou, který je oblíbeným místem pro práci, setkávání i večerní drink. V nabídce zde myslí i na milovníky poctivého chmelu bez alkoholu a nabízí skvělé nealko z vyhlášeného řemeslného pivovaru Zichovec.",descEn:"Kolektor in Holešovice, inside the Trade Fair Palace, is a stylish café, bar and cultural space with a distinctive industrial atmosphere, popular for working, meeting people and an evening drink alike. Anyone after honest hops without the alcohol is covered too, with excellent alcohol-free beer from the renowned craft brewery Zichovec.",lat:50.101006,lng:14.432805},
  {id:54,name:"Andělský pivovar",district:"Smíchov",hood:"Praha 5",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Andělský pivovar Nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11–0\nÚterý 11–0\nStředa 11–0\nČtvrtek 11–0\nPátek 11–0\nSobota 11–0\nNeděle 11–0",address:"Lidická 337/30, 150 00 Praha 5 – Smíchov",desc:"Andělský pivovar na Smíchově je craftový mikropivovar s restaurací přímo u Anděla, který kombinuje poctivě vařená řemeslná piva s moderní českou gastronomií. Vedle svých klasických ležáků a speciálů vaří i vlastní nealkoholické pivo, které nabízí plnou chmelovou chuť a skvělé osvěžení zcela bez alkoholu.",descEn:"Andělský pivovar in Smíchov is a craft microbrewery with a restaurant right by Anděl, combining carefully brewed beer with modern Czech cooking. Alongside its classic lagers and specials it brews its own alcohol-free beer, offering full hop flavour and proper refreshment with no alcohol at all.",lat:50.072321,lng:14.405945},
  {id:55,name:"NoD",district:"Staré Město",hood:"Praha 1",type:"Bar",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–1\nÚterý 16–1\nStředa 16–1\nČtvrtek 16–1\nPátek 16–3\nSobota 16–3\nNeděle 16–0",address:"Dlouhá 33, 110 00 Praha 1 – Staré Město",desc:"Kulturní prostor, galerie a bar v jednom, schovaný kousek od rušné Dlouhé. Pod jednou střechou se tu potkává divadlo, výstavy i večerní posezení u drinku, takže atmosféra se mění podle toho, co se zrovna děje v sále. Ke kuchyni s poledním menu i večerními burgery čepují dvě nealka z Vinohradského pivovaru — dvanáctku a Hazy Galaxy IPA.",descEn:"A cultural space, gallery and bar in one, tucked just off the busy Dlouhá street. Theatre, exhibitions and evening drinks share a roof here, so the mood shifts with whatever is happening in the hall. Alongside a kitchen serving lunch menus and evening burgers, two alcohol-free beers from Vinohradský pivovar are on tap — the twelve and the Hazy Galaxy IPA.",lat:50.090756,lng:14.425811},
  {id:56,name:"ROESEL beer & food",district:"Malá Strana",hood:"Praha 1",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–22\nÚterý 11–22\nStředa 11–22\nČtvrtek 11–22\nPátek 11–22\nSobota 11–22\nNeděle 12–20",address:"Mostecká 20, 118 00 Praha 1 – Malá Strana",desc:"Nenápadný bistro bar pár kroků od Karlova mostu, který navzdory poloze zůstal podnikem pro místní. Nabízí poctivou sezónní kuchyni, domácí pečivo a pečlivě vybraná česká piva. Nealko variantu tu najdete na čepu i v chladicím boxu, takže si vyberete podle nálady.",descEn:"An unassuming bistro bar a few steps from Charles Bridge that has, despite the location, stayed a place for locals. Honest seasonal cooking, house-baked bread and a carefully chosen range of Czech beers. The alcohol-free option is available on tap and from the fridge, so you can take it whichever way suits.",lat:50.087532,lng:14.405775},
  {id:57,name:"Bike7",district:"Nové Město",hood:"Praha 2",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 14–0\nÚterý 14–0\nStředa 14–0\nČtvrtek 14–0\nPátek 14–0\nSobota 11–0\nNeděle 11–0",address:"Rašínovo nábřeží, Náplavka, 128 00 Praha 2 – Nové Město",desc:"Bar v jedné z kobek na pražské Náplavce, poznáte ho podle charakteristických kruhových skleněných dveří. Uvnitř panuje klubová atmosféra s dobrou hudbou, venku se sedí přímo nad Vltavou. Vedle domácích limonád tu na čepu běží nealko pivo z Vinohradského pivovaru.",descEn:"A bar in one of the arched vaults along Prague's Náplavka embankment, recognisable by its distinctive round glass door. Inside there is a club atmosphere and good music; outside you sit directly above the Vltava. Alongside house lemonades, alcohol-free beer from Vinohradský pivovar is on tap.",lat:50.072749,lng:14.413854},
  {id:58,name:"Jarda Mayer café",district:"Smíchov",hood:"Praha 5",type:"Bar",serve:"Čepované",garden:"Ne",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–1\nÚterý 16–1\nStředa 16–1\nČtvrtek 16–1\nPátek 16–1\nSobota 17–1\nNeděle 17–0",address:"Staropramenná 22, 150 00 Praha 5 – Smíchov",desc:"Malý sousedský bar kousek od Anděla s nezaměnitelným interiérem a vstřícnou obsluhou. Je to typ podniku, kde se po pár návštěvách znáte s personálem i se štamgasty. Pivo tu ošetřují pečlivě, a to včetně nealko dvanáctky z Vinohradského pivovaru.",descEn:"A small neighbourhood bar near Anděl with an unmistakable interior and welcoming staff. It is the kind of place where, after a few visits, you know the bartenders and the regulars alike. The beer is looked after with care, the alcohol-free twelve from Vinohradský pivovar included.",lat:50.071944,lng:14.407222},
  {id:59,name:"Gazpacho Bar",district:"Holešovice",hood:"Praha 7",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 16–22\nÚterý 16–22\nStředa 16–22\nČtvrtek 16–22\nPátek 16–22\nSobota 16–22\nNeděle 16–22",address:"Ostrov Štvanice, 170 00 Praha 7 – Holešovice",desc:"Letní bar na Štvanici přímo u volejbalových kurtů, obklopený zelení uprostřed města. Grilují tu burgery, pouštějí hudbu z gramofonu a k tomu točí pivo včetně nealko varianty. Ideální zastávka po sportu nebo při procházce ostrovem.",descEn:"A summer bar on Štvanice island right by the volleyball courts, surrounded by greenery in the middle of the city. Burgers come off the grill, music comes off a turntable, and beer — alcohol-free included — comes off the tap. An ideal stop after sport or on a walk around the island.",lat:50.095917,lng:14.442310},
  {id:60,name:"Bean House",district:"Karlín",hood:"Praha 8",type:"Restaurace",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 11–21\nÚterý 11–21\nStředa 11–21\nČtvrtek 11–21\nPátek 11–21\nSobota 12–21\nNeděle 12–21",address:"Moláková 577/34, 186 00 Praha 8 – Karlín",desc:"Prostorná vietnamská restaurace u Invalidovny, kde se vaří poctivě a bez zbytečných kompromisů. K polévkám pho, závitkům i vegetariánským jídlům tu nabízejí domácí limonády a čepované pivo včetně nealko varianty. Klidné místo s rychlou obsluhou kousek od metra.",descEn:"A spacious Vietnamese restaurant near Invalidovna, cooking honestly and without needless compromise. Pho, spring rolls and vegetarian dishes come with house lemonades and draught beer, alcohol-free included. A calm place with quick service, a short walk from the metro.",lat:50.097123,lng:14.465119},
  {id:61,name:"Cafe DECADA",district:"Libeň",hood:"Praha 8",type:"Bar",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 9–0\nÚterý 9–0\nStředa 9–0\nČtvrtek 9–0\nPátek 9–0\nSobota 16–0\nNeděle 16–0",address:"Vacínova 876/10, 180 00 Praha 8 – Libeň",desc:"Kavárna a bar v jednom, který ráno otevírá u kávy a večer přechází do koktejlů a piva. V létě funguje příjemná zahrádka, uvnitř se střídají výstavy místních autorů. Nabídka nealko nápojů je tu nadstandardní a patří do ní i čepovaná nula z Vinohradského pivovaru.",descEn:"A café and bar in one, opening in the morning for coffee and shifting into cocktails and beer by evening. The garden is pleasant in summer, and the walls inside rotate exhibitions by local artists. The alcohol-free range is better than most and includes a draught zero from Vinohradský pivovar.",lat:50.104539,lng:14.477205},
  {id:62,name:"Diego Beer Bar",district:"Karlín",hood:"Praha 8",type:"Hospoda",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11–0\nÚterý 11–0\nStředa 11–0\nČtvrtek 11–0\nPátek 11–0\nSobota 16:30–0\nNeděle 16:30–22",address:"Sokolovská 467/114, 186 00 Praha 8 – Karlín",desc:"Karlínský pivní bar s industriálním interiérem a širokou nabídkou piv z malých pivovarů. Kohoutky i lednice rotují a nealko řemeslná pípa mezi nimi nechybí, takže si vybere i ten, kdo řídí. Kuchyně sází na tex-mex, od burritos po nachos.",descEn:"A Karlín beer bar with an industrial interior and a broad range of beer from small breweries. Both the taps and the fridges rotate, and an alcohol-free craft tap is always among them, so anyone driving is covered. The kitchen runs on tex-mex, from burritos to nachos.",lat:50.094763,lng:14.455238},
  {id:63,name:"Hedgehog café",district:"Hloubětín",hood:"Praha 9",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 15–21\nÚterý 15–21\nStředa 15–21\nČtvrtek 15–21\nPátek 15–21\nSobota 13–21\nNeděle 13–21",address:"Vozovna Hloubětín, 198 00 Praha 9 – Hloubětín",desc:"Kavárna a bar v areálu bývalé vozovny Hloubětín, přímo u skateparku Triangl Park. Prostorná venkovní terasa se stínem, promítací plátno a spousta místa pro děti i psy z ní dělají místo, kde se zdržíte déle, než jste plánovali. Na čepu je vedle klasiky i nealko pivo.",descEn:"A café and bar in the grounds of the former Hloubětín tram depot, right by the Triangl skatepark. A generous shaded terrace, a projection screen and plenty of room for children and dogs make it the kind of place you stay at longer than planned. Alongside the usual beers, there is an alcohol-free option on tap.",lat:50.106785,lng:14.527787},
  {id:64,name:"Bistro Moje Místo",district:"Vršovice",hood:"Praha 10",type:"Restaurace",serve:"Čepované",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 9–23\nÚterý 9–23\nStředa 9–23\nČtvrtek 9–23\nPátek 9–23\nSobota 9–23\nNeděle 9–23",address:"28. pluku 119/33, 100 00 Praha 10 – Vršovice",desc:"Vršovické bistro otevřené od rána do večera, které zvládne snídani, oběd i večerní pivo. Kuchyně míchá burgery, tacos a vegetariánské varianty, k tomu je v nabídce poctivá káva. V létě láká na zahrádku, kde si dáte i čepované nealko.",descEn:"A Vršovice bistro open from morning to evening, handling breakfast, lunch and an evening beer with equal ease. The kitchen mixes burgers, tacos and vegetarian options, and the coffee is taken seriously. In summer the garden draws people in, and draught alcohol-free beer is available there too.",lat:50.071769,lng:14.467644},
  {id:65,name:"Kino Pilotů",district:"Vršovice",hood:"Praha 10",type:"Bar",serve:"Čepované",garden:"Ne",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"}],hours:"Pondělí 10–22:30\nÚterý 10–22:30\nStředa 10–22:30\nČtvrtek 10–22:30\nPátek 10–22:30\nSobota 10–22:30\nNeděle 10–22:30",address:"Donská 168/19, 100 00 Praha 10 – Vršovice",desc:"Jedno z posledních pražských kin staré školy, kde se promítají artové filmy, festivaly i dokumenty. Bar v předsálí patří ke zážitku stejně jako samotná projekce. Vedle limonád a kávy tu čepují i nealko pivo, takže si film vychutnáte s plnohodnotnou nulou.",descEn:"One of the last old-school cinemas in Prague, screening art-house films, festivals and documentaries. The bar in the foyer is as much part of the experience as the projection itself. Alongside lemonades and coffee, alcohol-free beer is on tap, so the film comes with a proper zero in hand.",lat:50.071394,lng:14.446830},
  {id:66,name:"Pivní zastávka",district:"Vršovice",hood:"Praha 10",type:"Hospoda",serve:"Čepované",garden:"Ne",food:"Ne",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 15–22\nÚterý 15–22\nStředa 15–22\nČtvrtek 15–22\nPátek 15–22\nSobota Zavřeno\nNeděle Zavřeno",address:"28. pluku 11, 101 00 Praha 10 – Vršovice",desc:"Malá vršovická pivotéka se stovkou druhů piv v lednicích a rotující nabídkou na čepu. Personál rád poradí a trefí se i do náročnějšího vkusu. Nealko tu neberou jako nutné zlo — řemeslné nuly se objevují na čepu i v lednicích podle aktuální nabídky.",descEn:"A small Vršovice bottle shop with a hundred kinds of beer in the fridges and a rotating selection on tap. The staff enjoy advising and will meet even demanding tastes. Alcohol-free is not treated as a necessary evil here — craft zeros turn up on tap and in the fridges depending on what is available.",lat:50.070965,lng:14.461802},
  {id:67,name:"Picoška Napoletana",district:"Brandýs nad Labem",hood:"Středočeský kraj",type:"Restaurace",serve:"Čepované",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí Zavřeno\nÚterý Zavřeno\nStředa 11:30–22\nČtvrtek 11:30–22\nPátek 11:30–22\nSobota 11:30–22\nNeděle 11:30–20",address:"Pekařská 12/2, Stará Boleslav, 250 01 Brandýs nad Labem",desc:"Pizzerie ve Staré Boleslavi, která dělá neapolskou pizzu podle všech pravidel a patří k nejlepším v okolí. Kromě pizzy stojí za pozornost i těstoviny a dezerty. K italské kuchyni tu nabízejí české pivo včetně nealko varianty na čepu i v plechovce.",descEn:"A pizzeria in Stará Boleslav making Neapolitan pizza by the book, and among the best in the area. Beyond pizza, the pasta and desserts are worth attention. Czech beer accompanies the Italian cooking, with an alcohol-free version on tap and in can.",lat:50.187055,lng:14.658204},
  {id:68,name:"Baráčnická rychta",district:"Malá Strana",hood:"Praha 1",type:"Restaurace",serve:"Lahvové",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 11:30–22:30\nÚterý 11:30–22:30\nStředa 11:30–22:30\nČtvrtek 11:30–22:30\nPátek 11:30–22:30\nSobota 11:30–22:30\nNeděle 11:30–22:30",address:"Tržiště 23, 118 00 Praha 1 – Malá Strana",desc:"Historická malostranská restaurace s více než stoletou tradicí, schovaná kousek od turistických tras. Vaří poctivou českou klasiku od svíčkové po kachnu a v létě otevírá kouzelnou zahradu pod vzrostlými stromy. V chladicím boxu najdete i řemeslné nealko pivo.",descEn:"A historic Malá Strana restaurant with more than a century behind it, tucked just off the tourist routes. The kitchen turns out Czech classics from svíčková to duck, and summer opens a charming garden under mature trees. The fridge holds craft alcohol-free beer too.",lat:50.087963,lng:14.400164},
  {id:69,name:"Přátelé coffee & wine friends",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Lahvové",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 16–0\nÚterý 16–0\nStředa 16–0\nČtvrtek 16–0\nPátek 16–0\nSobota 16–0\nNeděle 16–23",address:"Rumunská 14/27, 120 00 Praha 2 – Vinohrady",desc:"Vinohradský vinný bar s útulným interiérem, houpačkou u prostředního stolu a klidným dvorkem. Personál se o víno i hosty zajímá a rád doporučí. K sýrovým prkénkům a olivám je v nabídce i řemeslné nealko pivo pro ty, kdo zrovna nepijí víno.",descEn:"A Vinohrady wine bar with a snug interior, a swing at the central table and a quiet courtyard. The staff care about the wine and about their guests, and are happy to recommend. Alongside cheese boards and olives, craft alcohol-free beer is there for anyone not drinking wine that evening.",lat:50.074463,lng:14.434112},
  {id:70,name:"Bistro Habibi",district:"Vyšehrad",hood:"Praha 2",type:"Restaurace",serve:"Lahvové",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí Zavřeno\nÚterý 17–22\nStředa 17–22\nČtvrtek 17–22\nPátek 17–22\nSobota 16–22\nNeděle Zavřeno",address:"Vratislavova 21/1, 128 00 Praha 2 – Vyšehrad",desc:"Rodinné bistro pod Vyšehradem s jordánskou a libanonskou kuchyní, které si rychle získalo pověst jednoho z nejpřátelštějších podniků v Praze. Mezze platter, hummus i čočková polévka tu chutnají jako doma. K jídlu se hodí vychlazené nealko pivo z lednice.",descEn:"A family bistro below Vyšehrad serving Jordanian and Lebanese food, which has quickly built a reputation as one of the friendliest places in Prague. The mezze platter, hummus and lentil soup all taste like someone's home kitchen. A chilled alcohol-free beer from the fridge suits the food well.",lat:50.066382,lng:14.419080},
  {id:71,name:"Kavárna Kaaba",district:"Vinohrady",hood:"Praha 2",type:"Bar",serve:"Lahvové",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 8–0\nÚterý 8–0\nStředa 8–0\nČtvrtek 8–0\nPátek 8–0\nSobota 9–0\nNeděle 10–23",address:"Mánesova 1624, 120 00 Praha 2 – Vinohrady",desc:"Vinohradská kavárna s retro interiérem, která je od rána otevřená pro snídaně a večer se mění v příjemný bar. Domácí koláče, dobrá káva a vstřícná obsluha z ní udělaly stálici čtvrti. V nabídce nechybí ani řemeslné nealko pivo.",descEn:"A Vinohrady café with a retro interior, open from the morning for breakfast and turning into a comfortable bar in the evening. House-baked cakes, good coffee and welcoming staff have made it a fixture of the neighbourhood. Craft alcohol-free beer is part of the range.",lat:50.078617,lng:14.436953},
  {id:72,name:"better than clasico",district:"Žižkov",hood:"Praha 3",type:"Restaurace",serve:"Lahvové",garden:"Ne",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 12–15, 17–22\nÚterý Zavřeno\nStředa 12–15, 17–22\nČtvrtek 12–15, 17–22\nPátek 12–15, 17–22\nSobota 12–15, 17–22\nNeděle 12–15, 17–22",address:"Hartigova 2B, 130 00 Praha 3 – Žižkov",desc:"Žižkovské bistro s korejskou fusion kuchyní a výrazným minimalistickým interiérem. Obsluha se o hosty stará s nakažlivou energií, jídlo má čisté a odvážné chutě. K ssamjang kuřeti nebo tofu si dáte i chlazené nealko pivo.",descEn:"A Žižkov bistro serving Korean fusion in a striking minimalist room. The staff look after guests with infectious energy and the food has clean, bold flavours. A chilled alcohol-free beer goes well with the ssamjang chicken or the tofu.",lat:50.087228,lng:14.453594},
  {id:73,name:"Never Enough",district:"Vinohrady",hood:"Praha 3",type:"Bar",serve:"Lahvové",garden:"Ano",food:"Ne",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 12–19\nÚterý 12–19\nStředa 12–19\nČtvrtek 12–19\nPátek 12–19\nSobota 11–18\nNeděle 12–18",address:"nám. J. z Poděbrad 1573/18, 130 00 Praha 3 – Vinohrady",desc:"Streetwearová značka z Vinohrad a Žižkova, která svůj showroom na náměstí Jiřího z Poděbrad pojala jako otevřený prostor pro setkávání. Kolem značky budují komunitu lidí se zájmem o lidská práva a udržitelnost a podporují projekty, které jim dávají smysl. Zboží si prohlédnete u malého baru s posezením, kde si k tomu dáte pivo včetně poctivé nealko varianty.",descEn:"A streetwear label from Vinohrady and Žižkov whose showroom on náměstí Jiřího z Poděbrad is run as an open space for meeting people. The brand builds a community around human rights and sustainability, and supports projects it believes in. You browse the clothes beside a small bar with seating, where beer — an honest alcohol-free version included — is served.",lat:50.077683,lng:14.452443},
  {id:74,name:"Naše maso Holešovická tržnice",district:"Holešovice",hood:"Praha 7",type:"Restaurace",serve:"Lahvové",garden:"Ano",food:"Ano",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí Zavřeno\nÚterý 12–21\nStředa 12–21\nČtvrtek 12–21\nPátek 10–21\nSobota 9–22\nNeděle 11–17",address:"Hala 28, Bubenské nábř. 306/13, 170 00 Praha 7 – Holešovice",desc:"Řeznictví a bistro v Hale 28 v Pražské tržnici, kde maso pochází z vlastního chovu a zpracovává se na místě. Tatarák, sekaná i burger patří ke špičce v Praze, venkovní posezení v areálu tržnice je příjemným bonusem. Vedle limonád tu najdete i nealko pivo.",descEn:"A butcher's and bistro in Hall 28 of the Prague Market Halls, where the meat comes from the company's own farm and is processed on site. The steak tartare, meatloaf and burger rank among the best in Prague, and the outdoor seating in the market grounds is a welcome bonus. Alongside lemonades there is alcohol-free beer.",lat:50.100378,lng:14.446105},
  {id:75,name:"Galerie piva",district:"Vršovice",hood:"Praha 10",type:"Hospoda",serve:"Čepované",garden:"Ne",food:"Ne",craft:"Craft",beers:[{name:"Podle aktuální nabídky",cat:"Craft",serve:"Čepované"},{name:"Podle aktuální nabídky",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí 14–22\nÚterý 14–22\nStředa 14–22\nČtvrtek 14–22\nPátek 14–22\nSobota 14–22\nNeděle 14–22",address:"Krymská 138/36, 101 00 Praha 10 – Vršovice",desc:"Vršovická pivotéka a výčep v jednom, kde se na stěnách střídají díla místních výtvarníků a dají se i koupit. Nabídka na čepu rotuje, lednice jsou plné českých i zahraničních speciálů. Nealko craftu tu věnují stejnou pozornost jako alkoholickým pivům.",descEn:"A Vršovice bottle shop and taproom in one, where the walls rotate work by local artists — all of it for sale. The taps change constantly and the fridges are full of Czech and international specials. Alcohol-free craft beer gets exactly the same attention here as everything with alcohol in it.",lat:50.070601,lng:14.450810},
  {id:76,name:"Výčep Káraný",district:"Káraný",hood:"Středočeský kraj",type:"Bar",serve:"Čepované",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Čepované"},{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Lahvové"}],hours:"Pondělí Zavřeno\nÚterý Zavřeno\nStředa 15–19\nČtvrtek 15–19\nPátek 15–19\nSobota 12–19\nNeděle 12–19",address:"U Vodárny 193, 250 75 Káraný",desc:"Výčep přímo v areálu druhého pivovaru Vinohradského pivovaru v Káraném, kde se vaří z místní podzemní vody filtrované štěrkopísky Jizery. Moderní budova s posezením uvnitř i venku je oblíbenou zastávkou cyklistů a výletníků. K domácím klobásám a sýru si dáte nealko dvanáctku z čepu i nealko Hazy Galaxy IPA v plechu.",descEn:"A taproom inside the grounds of Vinohradský pivovar's second brewery in Káraný, where the beer is brewed with local groundwater filtered through the gravel beds of the Jizera. The modern building has seating indoors and out and is a favourite stop for cyclists and day trippers. House sausages and cheese come with the alcohol-free twelve on tap and alcohol-free Hazy Galaxy IPA in can.",lat:50.176888,lng:14.733979},
  {id:77,name:"Kafé Vzlet",district:"Vršovice",hood:"Praha 10",type:"Bar",serve:"Lahvové",garden:"Ano",food:"Drobné občerstvení",craft:"Craft",beers:[{name:"Vinohradská 12 nealko",cat:"Craft",serve:"Lahvové"},{name:"Vinohradská Hazy Galaxy IPA",cat:"Craft",serve:"Lahvové"},{name:"Maisel´s IPA Alkoholfrei",cat:"Tradiční",serve:"Lahvové"},{name:"Maisel´s Weisse alkoholfrei",cat:"Tradiční",serve:"Lahvové"}],hours:"Pondělí 14–22\nÚterý 14–22\nStředa 14–22\nČtvrtek 14–22\nPátek 14–22\nSobota 14–22\nNeděle 14–22",address:"Holandská 669/1, 101 00 Praha 10 – Vršovice",desc:"Kulturní centrum ve zrekonstruované funkcionalistické budově bývalého kina a divadla, kde se pod jednou střechou potkává divadelní sál, galerie, co-workingové prostory i kavárna s barem. Velká venkovní terasa patří v teplých měsících k nejpříjemnějším místům ve Vršovicích a je vstřícná k dětem i psům. Nealko nabídka je nadstandardně široká: dvě craftové nuly z Vinohradského pivovaru a dvě německé pšeničné od Maisela, všechny v plechu nebo lahvi.",descEn:"A cultural centre in the restored functionalist building of a former cinema and theatre, bringing a performance hall, gallery, co-working space and a café bar under one roof. In the warmer months the large outdoor terrace is among the most pleasant places in Vršovice, and it welcomes children and dogs. The alcohol-free range is unusually broad: two craft zeros from Vinohradský pivovar and two German wheat beers from Maisel, all in can or bottle.",lat:50.069926,lng:14.454795}
];
